<script setup lang="ts">
import { computed } from 'vue'
import AppIcon from '../../../../shared/components/layout/AppIcon.vue'
import type { FinancialReportSummary } from '../../../projects/financial-report/types/financialReport'

const props = defineProps<{ summary: FinancialReportSummary; periodLabel: string }>()
const money = new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 })
const received = computed(() => Number(props.summary.received))
const expenses = computed(() => Number(props.summary.expenses))
const maxFlow = computed(() => Math.max(received.value, expenses.value, 1))
const receivedWidth = computed(() => `${Math.max(2, received.value / maxFlow.value * 100)}%`)
const expenseWidth = computed(() => `${Math.max(2, expenses.value / maxFlow.value * 100)}%`)
</script>

<template>
  <section class="finance-dashboard" aria-labelledby="finance-dashboard-title">
    <div class="finance-heading"><div><span class="section-overline"><i></i> KEUANGAN</span><h2 id="finance-dashboard-title">Ringkasan keuangan</h2><p>{{ periodLabel }} · dibandingkan dengan pengeluaran pada periode yang sama</p></div><RouterLink class="report-link" to="/reports/financial">Lihat laporan <AppIcon name="arrow-up-right" :size="14" /></RouterLink></div>
    <div class="finance-cards">
      <article class="finance-card"><span><i class="metric-icon invoice"><AppIcon name="invoice" :size="16" /></i>Invoice terbit</span><strong>{{ money.format(Number(summary.invoice_issued)) }}</strong><small>Nilai invoice yang diterbitkan pada periode ini</small></article>
      <article class="finance-card"><span><i class="metric-icon received"><AppIcon name="wallet" :size="16" /></i>Penerimaan</span><strong>{{ money.format(received) }}</strong><small>Dana masuk yang sah pada periode ini</small></article>
      <article class="finance-card"><span><i class="metric-icon expense"><AppIcon name="receipt" :size="16" /></i>Pengeluaran</span><strong>{{ money.format(expenses) }}</strong><small>Termasuk operasional tim {{ money.format(Number(summary.operational_expenses)) }}</small></article>
      <article class="finance-card"><span><i class="metric-icon outstanding"><AppIcon name="invoice" :size="16" /></i>Sisa tagihan</span><strong>{{ money.format(Number(summary.outstanding)) }}</strong><small>Saldo terkini seluruh invoice terbit</small></article>
    </div>
    <div class="cashflow-card"><div class="cashflow-copy"><span>Arus kas bersih periode ini</span><strong :class="{ negative: Number(summary.cash_flow) < 0 }">{{ money.format(Number(summary.cash_flow)) }}</strong></div><div class="cashflow-bars" aria-label="Perbandingan penerimaan dan pengeluaran"><div class="bar-row"><span>Penerimaan</span><div class="bar-track"><i class="income-bar" :style="{ width: receivedWidth }"></i></div><strong>{{ money.format(received) }}</strong></div><div class="bar-row"><span>Pengeluaran</span><div class="bar-track"><i class="expense-bar" :style="{ width: expenseWidth }"></i></div><strong>{{ money.format(expenses) }}</strong></div></div></div>
  </section>
</template>

